const listOwnerMemoryTopics = `-- name: ListOwnerMemoryTopics :many

SELECT model_id, name, scope, seed, status, position, last_refresh_at, last_hit_at, created_at, updated_at FROM owner_memory_topics ORDER BY seed DESC, position, created_at, model_id
`

// ---------- topics ----------
func (q *Queries) ListOwnerMemoryTopics(ctx context.Context) ([]OwnerMemoryTopic, error) {
	rows, err := q.db.QueryContext(ctx, listOwnerMemoryTopics)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []OwnerMemoryTopic{}
	for rows.Next() {
		var i OwnerMemoryTopic
		if err := rows.Scan(
			&i.ModelID,
			&i.Name,
			&i.Scope,
			&i.Seed,
			&i.Status,
			&i.Position,
			&i.LastRefreshAt,
			&i.LastHitAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

